  "Theme cards show real Today screenshots with a different exercise and animation style for each theme.": "थीम कार्ड असली Today स्क्रीनशॉट दिखाते हैं, हर थीम के लिए अलग व्यायाम और एनीमेशन स्टाइल।",
  "Try themes live in Settings → Appearance: opens Today with a small switcher floating at the top of the screen, one letter per theme (A Original to G Course). Hover a letter to see its name, keep using any page while you compare, and close it with × (or Escape). It stays open across pages and reloads until you close it.": "सेटिंग्स → अपीयरेंस में थीम लाइव आज़माएँ: स्क्रीन के ऊपर तैरते छोटे स्विचर के साथ Today खुलता है, हर थीम के लिए एक अक्षर (A ओरिजिनल से G कोर्स तक)। नाम देखने के लिए अक्षर पर हॉवर करें, तुलना करते समय किसी भी पेज का इस्तेमाल करें, और × (या Escape) से बंद करें। आपके बंद करने तक यह पेज बदलने पर भी खुला रहता है।",
  "Theme and animation screenshots stay visible in the README while technical details remain collapsed.": "README में थीम और एनीमेशन स्क्रीनशॉट दिखते रहते हैं जबकि तकनीकी विवरण संक्षिप्त रहते हैं।",
