  "Your data saves to <code>{dir}/</code> on this computer. Git ignores this folder. Copy it or export a backup below to keep a spare copy.": "आपका डेटा इस कंप्यूटर पर <code>{dir}/</code> में सहेजा जाता है। Git इस फ़ोल्डर को अनदेखा करता है। अतिरिक्त कॉपी के लिए इसे कॉपी करें या नीचे बैकअप एक्सपोर्ट करें।",
  "Your details and workouts save in the <code>{dir}/</code> folder on this computer.": "आपकी जानकारी और वर्कआउट इस कंप्यूटर पर <code>{dir}/</code> फ़ोल्डर में सहेजे जाते हैं।",
  "The local server is unavailable, so your data saves only in this browser. Export a backup regularly, or run <code>npm start</code> to save to files on your computer.": "लोकल सर्वर उपलब्ध नहीं है, इसलिए आपका डेटा सिर्फ़ इस ब्राउज़र में सहेजा जाता है। नियमित रूप से बैकअप एक्सपोर्ट करें, या अपने कंप्यूटर पर फ़ाइलों में सहेजने के लिए <code>npm start</code> चलाएँ।",
  "Your details and workouts are saved in this browser because the local server isn't running. Run <code>npm start</code> to save them as files.": "लोकल सर्वर नहीं चल रहा है, इसलिए आपकी जानकारी और वर्कआउट इस ब्राउज़र में सहेजे गए हैं। फ़ाइलों में सहेजने के लिए <code>npm start</code> चलाएँ।",
