  "No strength sets logged in these dates. Choose a longer interval or record a set during your workout.": "इन तारीखों में कोई स्ट्रेंथ सेट लॉग नहीं हुआ। बड़ी अवधि चुनें या वर्कआउट के दौरान सेट रिकॉर्ड करें।",
