  "Weekly averages follow the selected interval, and long-term chart labels stay readable.": "साप्ताहिक औसत चुनी हुई अवधि के अनुसार होते हैं, और लंबी अवधि के चार्ट लेबल पढ़ने योग्य रहते हैं।",
  "Progress shows exact interval dates and applies them to all charts, tables and summary totals.": "प्रगति सटीक तारीखें दिखाती है और उन्हें सभी चार्ट, टेबल और कुल योग पर लागू करती है।",
  "Grouped progress intervals include This week, Last week, This month, Last month and Since beginning.": "प्रगति की अवधियों में इस सप्ताह, पिछले सप्ताह, इस महीने, पिछले महीने और शुरुआत से शामिल हैं।",
