  "Standing calf raises": "खड़े होकर काफ रेज़",
  "Seated calf raises": "बैठकर काफ रेज़",
  "Exercises with multiple movements (such as the dynamic warm-up, jumps, calf raises, pull-ups & chin-ups, dead hangs, heel drops & stomps, knee & leg raises, single-leg RDL & toe touch, external rotation, neck resistance and interval moves) now have 1–5 videos per movement that switch automatically as the 3D animation changes movement.": "कई मूवमेंट वाले व्यायाम (जैसे डायनामिक वार्म-अप, जंप्स, काफ रेज़, पुल-अप और चिन-अप, डेड हैंग्स, हील ड्रॉप्स और स्टॉम्प्स, नी और लेग रेज़, सिंगल-लेग RDL और टो टच, एक्सटर्नल रोटेशन, नेक रेज़िस्टेंस और इंटरवल मूव्स) में अब हर मूवमेंट के लिए 1–5 वीडियो हैं, जो 3D एनीमेशन का मूवमेंट बदलते ही अपने आप बदल जाते हैं।",
  "Fixed dumbbells and bands passing through the body in goblet squats, swings, rows, presses, lunges, woodchops, chest flies and seated calf raises.": "गोब्लेट स्क्वॉट्स, स्विंग्स, रोज़, प्रेस, लंज, वुडचॉप्स, चेस्ट फ्लाईज़ और बैठकर काफ रेज़ में शरीर के बीच से गुजरने वाले फिक्स्ड डम्बल और बैंड्स।",
  "For less noise, drive the knee up quickly with a calf raise, keeping the supporting foot on the floor.": "कम शोर के लिए काफ रेज़ के साथ घुटना तेज़ी से ऊपर उठाएँ, सहायक पैर फर्श पर रखें।",
  "Quiet version: explosive squat to calf raise without leaving the floor.": "शांत वर्ज़न: फर्श छोड़े बिना विस्फोटक स्क्वॉट से काफ रेज़।",
  "Dumbbells stay in the hands through whole reps: the goblet squat cups the weight at the chest, the swing passes between the thighs with relaxed arms, and reverse lunges, step-ups and calf raises hang level at the sides.": "पूरे रेप में डम्बल हाथों में रहते हैं: गोब्लेट स्क्वॉट में वज़न छाती पर रहता है, स्विंग में ढीले हाथों के साथ जाँघों के बीच से गुजरता है, और रिवर्स लंज, स्टेप-अप्स तथा काफ रेज़ में डम्बल बगल में सीधे लटके रहते हैं।",
  "90 s": "90 सेकंड",
  "60 s": "60 सेकंड",
  "45 s": "45 सेकंड",
  "30 s": "30 सेकंड",
  "120 s": "120 सेकंड",
  "75 s": "75 सेकंड",
  "1 min": "1 मिनट",
  "Do Bryan's two physical-therapist exercises to fatigue today. He does them twice a week.": "आज ब्रायन के दोनों फिज़िकल थेरेपिस्ट व्यायाम थकान तक करें। वे इन्हें हफ्ते में दो बार करते हैं।",
  "Bryan: to fatigue, 2×/wk": "ब्रायन: थकान तक, हफ्ते में 2×",
  "2 × 30 s/leg, eyes open": "2 × 30 सेकंड/पैर, आँखें खुली",
  "Do Bryan’s Thursday Norwegian 4×4 indoors, then the stability exercises from his official protocol.": "ब्रायन का गुरुवार वाला नॉर्वेजियन 4×4 इनडोर करें, फिर उनके आधिकारिक प्रोटोकॉल के स्टेबिलिटी व्यायाम करें।",
  "Dose text such as \"2 s hold\", \"eyes open\" and \"per side\" now translates.": "“2 सेकंड होल्ड”, “आँखें खुली” और “प्रति साइड” जैसा डोज़ टेक्स्ट अब ट्रांसलेट होता है।",
  "Reset workout history in Settings → Your data clears every logged day while keeping your profile, equipment, settings and add-ons.": "सेटिंग्स → आपका डेटा में वर्कआउट हिस्ट्री रीसेट करने पर हर लॉग किया दिन साफ़ हो जाता है, जबकि आपकी प्रोफ़ाइल, उपकरण, सेटिंग्स और ऐड-ऑन बने रहते हैं।",
  "This backup has {days} logged days{mixed}. Choose Replace all to overwrite your current data. Cancel merges the backup instead; its days overwrite matching dates.": "इस बैकअप में {days} लॉग किए दिन हैं{mixed}। अपना मौजूदा डेटा बदलने के लिए “सब बदलें” चुनें। रद्द करने पर बैकअप मर्ज हो जाएगा; इसके दिन मिलती तारीखों को बदल देंगे।",
  "If you have been inactive for a while, are over 50 or have any heart condition, get a basic check-up (blood pressure, resting ECG) before your first all-out intervals.": "अगर आप कुछ समय से निष्क्रिय हैं, 50 से ज़्यादा उम्र के हैं या आपको दिल की कोई बीमारी है, तो पहले ऑल-आउट इंटरवल्स से पहले बेसिक चेक-अप (ब्लड प्रेशर, रेस्टिंग ECG) कराएँ।",
